def FactorsThroughWith (S : Z →L[𝕜] W) (T : X →L[𝕜] Y) (C : ℝ) : Prop :=
  ∃ U : Y →L[𝕜] W, ∃ V : Z →L[𝕜] X,
    (U.comp T).comp V = S ∧ ‖U‖ * ‖V‖ ≤ C

